options.content:
{
  "id": 1,
  "type": "marcusolsson-dynamictext-panel",
  "title": "New panel",
  "gridPos": {
    "x": 0,
    "y": 0,
    "h": 18,
    "w": 14
  },
  "fieldConfig": {
    "defaults": {
      "thresholds": {
        "mode": "absolute",
        "steps": [
          {
            "color": "green",
            "value": null
          },
          {
            "color": "red",
            "value": 80
          }
        ]
      }
    },
    "overrides": []
  },
  "pluginVersion": "5.7.0",
  "targets": [
    {
      "editorMode": "code",
      "format": "table",
      "rawQuery": true,
      "rawSql": "SELECT \n  mypcb['defected'] AS defected,\n  mypcb['material_info'] AS material_info,\n  mypcb['heatsink_number'] AS heatsink_size,\n  mypcb['url'] AS image_url,\n  mypcb['id'] AS pcb_id,\n  mypcb['defect_loc_x'] AS x,\n  mypcb['defect_loc_y'] AS y,\n  mypcb['departured'] AS departured\nFROM \"doc\".\"etrobot\"\nWHERE mypcb['url'] IS NOT NULL\nORDER BY time_index DESC\nLIMIT 1;",
      "refId": "A",
      "sql": {
        "columns": [
          {
            "parameters": [],
            "type": "function"
          }
        ],
        "groupBy": [
          {
            "property": {
              "type": "string"
            },
            "type": "groupBy"
          }
        ],
        "limit": 50
      }
    }
  ],
  "datasource": {
    "uid": "CrateDB_pcbmetada"
  },
  "options": {
    "renderMode": "everyRow",
    "editors": [],
    "editor": {
      "language": "html",
      "format": "auto"
    },
    "wrap": false,
    "contentPartials": [],
    "content": " <h2>Defective PCB Info</h2>\n      <p><strong>ID:</strong> {{@root.pcb_id}}</p>\n      <p><strong>Defected:</strong> {{@root.defected}}</p>\n      <p><strong>Material:</strong> {{@root.material_info}}</p>\n      <p><strong>Defect Location:</strong> ({{@root.x}}, {{@root.y}})</p>\n      <p><strong>Departured:</strong> {{@root.departured}}</p>\n\n      <figure style=\"text-align: center;\">\n        <img src=\"{{{ @root.image_url }}}\" alt=\"Defective PCB\" width=\"400\" style=\"border: 1px solid #ccc;\" />\n        <figcaption style=\"font-size: 14px; color: #666; margin-top: 8px;\">\n          Defective PCB detected on {{@root.departured}}\n        </figcaption>\n      </figure>",
    "defaultContent": "The query didn't return any results.",
    "helpers": "",
    "afterRender": "",
    "externalStyles": [],
    "styles": ""
  }
}
